  if(animationEditing&&ActiveTrack==null){animationGraph.Children.Clear();animationTime.Text=UiLanguage.Text("Добавьте выбранный объект в анимацию кнопкой +");return;}if(ActiveClip!=null)animationTime.Text=UiLanguage.Text("Кадр")+": "+animationFrame.Value.ToString("F1")+" / "+ActiveClip.LastFrame+"    "+(animationFrame.Value/ActiveClip.Fps).ToString("F2")+" s";var track=ActiveTrack;if(track==null){animationGraph.Children.Clear();drawnGraphTrack=null;return;}double w=Math.Max(1,animationGraph.ActualWidth),h=animationGraph.Height;if(ReferenceEquals(track,drawnGraphTrack)&&drawnGraphChannel==animationGraphChannel.SelectedIndex&&drawnGraphLength==ActiveClip!.LastFrame&&drawnGraphWidth==w&&drawnGraphHeight==h)return;drawnGraphTrack=track;drawnGraphChannel=animationGraphChannel.SelectedIndex;drawnGraphLength=ActiveClip!.LastFrame;drawnGraphWidth=w;drawnGraphHeight=h;animationGraph.Children.Clear();var sample=track.Sampler();float[] Values(AnimationPose pose)=>animationGraphChannel.SelectedIndex switch{0=>pose.Position,2=>pose.Scale,_=>pose.Rotation};float[] all=track.Keys.SelectMany(k=>Values(k.Pose)).ToArray();double lo=Math.Min(0,all.Min()),hi=Math.Max(1,all.Max());var colours=new[]{Colors.IndianRed,Colors.MediumSeaGreen,Colors.CornflowerBlue};
